// Generates src/styles/tokens.css (CSS custom properties) from the app's
// resolved design tokens in src/tokens/tokens.resolved.json. Do not edit the
// output by hand; edit tokens in the app repo, then `npm run sync`.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const tokens = JSON.parse(readFileSync(resolve(root, 'src/tokens/tokens.resolved.json'), 'utf8'));

const kebab = (s) => s.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();
const px = (n) => `${n}px`;
const bezier = (e) => `cubic-bezier(${e.join(', ')})`;

function colors(mode) {
  const out = [];
  for (const [k, v] of Object.entries(tokens.color[mode])) out.push(`--color-${kebab(k)}: ${v};`);
  for (const [k, v] of Object.entries(tokens.color.chart[mode])) out.push(`--color-chart-${kebab(k)}: ${v};`);
  return out;
}

const base = [];
for (const [k, v] of Object.entries(tokens.space.scale)) base.push(`--space-${k}: ${px(v)};`);
for (const [k, v] of Object.entries(tokens.space.alias)) base.push(`--space-${kebab(k)}: ${px(v)};`);
for (const [k, v] of Object.entries(tokens.type.scale)) {
  const n = kebab(k);
  base.push(
    `--type-${n}-size: ${px(v.size)};`,
    `--type-${n}-line-height: ${px(v.lineHeight)};`,
    `--type-${n}-weight: ${v.weight};`,
    `--type-${n}-letter-spacing: ${px(v.letterSpacing)};`,
  );
}
for (const [k, v] of Object.entries(tokens.motion.duration)) base.push(`--motion-duration-${kebab(k)}: ${v}ms;`);
for (const [k, v] of Object.entries(tokens.motion.easing)) base.push(`--motion-easing-${kebab(k)}: ${bezier(v)};`);
for (const [k, v] of Object.entries(tokens.icon.size)) base.push(`--icon-size-${kebab(k)}: ${px(v)};`);
for (const [k, v] of Object.entries(tokens.state.layerOpacity)) base.push(`--state-layer-${kebab(k)}: ${v};`);
base.push(
  `--focus-ring-color: ${tokens.state.focusRing.color};`,
  `--focus-ring-width: ${px(tokens.state.focusRing.width)};`,
  `--focus-ring-offset: ${px(tokens.state.focusRing.offset)};`,
);

const indent = (lines, n) => lines.map((l) => ' '.repeat(n) + l).join('\n');
const css = `/* Generated by scripts/tokens-to-css.mjs from src/tokens/tokens.resolved.json. Do not edit. */
:root {
  color-scheme: light dark;
${indent(base, 2)}
${indent(colors('light'), 2)}
}

@media (prefers-color-scheme: dark) {
  :root {
${indent(colors('dark'), 4)}
  }
}
`;

writeFileSync(resolve(root, 'src/styles/tokens.css'), css);
console.log('wrote src/styles/tokens.css');
